use super::*;
fn debit(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u64){assert!(p.fits(*bank));assert!(work<=*fuel);bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).unwrap();}
#[test]
fn actual_sequence_storage_admission_keeps_backing_on_caller_before_return_and_reports_null_work(){let mut retirement_actual=None;let mut retirement_work=0;
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let count=row["count"].as_u64().unwrap()as usize;let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.maximum_capacity_bytes,&mut callback);let mut output=None;let mut frame=crate::native_decoding::NativeReceivingEffect::default();let d=<Vec<u64>as NativeSequenceCollection<u64>>::storage_demand(count).unwrap();assert_eq!(d.copy_bytes,std::mem::size_of::<Vec<u64>>());
 for g in [RetainedCloneGrant{maximum_items:0,..bank},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..bank},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..bank},RetainedCloneGrant{maximum_depth:0,..bank}]{let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||crate::source_fixture::receive(&mut control,g,crate::source_fixture::WorkLoan::new(&fuel,fuel),|c|<Vec<u64>as NativeSequenceCollection<u64>>::admit_storage(&mut output,count,&mut frame,c,fuel,g)));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert!(output.is_none());}
 let((turn,attempts),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||crate::source_fixture::receive(&mut control,RetainedCloneGrant{maximum_items:1,..bank},crate::source_fixture::WorkLoan::new(&fuel,fuel),|c|<Vec<u64>as NativeSequenceCollection<u64>>::admit_storage(&mut output,count,&mut frame,c,fuel,RetainedCloneGrant{maximum_items:1,..bank}))));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,1);fuel-=turn.work;assert!(turn.result.is_err());assert!(output.is_none());assert_eq!(control.owned_bytes(),0);
 let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||crate::source_fixture::receive(&mut control,RetainedCloneGrant{maximum_items:1,..bank},crate::source_fixture::WorkLoan::new(&fuel,fuel),|c|<Vec<u64>as NativeSequenceCollection<u64>>::admit_storage(&mut output,count,&mut frame,c,fuel,RetainedCloneGrant{maximum_items:1,..bank})));assert_eq!(turn.work,1);let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(p.copied_bytes,d.copy_bytes);debit(&mut bank,&mut fuel,p,turn.work);let pointer=output.as_ref().unwrap().as_ptr();let capacity=output.as_ref().unwrap().capacity();assert_eq!(serde_json::to_value(output.as_ref().unwrap()).unwrap(),row["empty"]);let(cached,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||crate::source_fixture::receive(&mut control,Default::default(),crate::source_fixture::WorkLoan::new(&fuel,fuel),|c|<Vec<u64>as NativeSequenceCollection<u64>>::admit_storage(&mut output,count,&mut frame,c,fuel,Default::default())));assert_eq!(cached.work,0);let error=cached.result.unwrap_err();assert_eq!(error.allocation_refusal.as_ref().unwrap().kind,ValueRefusalKind::InvariantViolated);assert_eq!(error.retained_progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(output.as_ref().unwrap().as_ptr(),pointer);assert_eq!(output.as_ref().unwrap().capacity(),capacity);

 let mut donor=Some(row["push"]["value"].as_u64().unwrap());for case in row["push"]["cases"].as_array().unwrap(){let maximum=case["maximum"].as_u64().unwrap().min(fuel);let g=RetainedCloneGrant{maximum_items:1,..bank};let quoted=<Vec<u64>as NativeSequenceCollection<u64>>::push_work_demand(output.as_ref().unwrap(),0).unwrap();assert_eq!(quoted,row["push"]["work"].as_u64().unwrap());let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||<Vec<u64>as NativeSequenceCollection<u64>>::push_step(output.as_mut().unwrap(),0,&mut donor,maximum,g));assert_eq!(heap,(0,0));assert_eq!(turn.work,case["work"].as_u64().unwrap());let step=turn.result.unwrap();let accepted=matches!(step,RetainedCloneStep::Complete(_));assert_eq!(accepted,case["accepted"].as_bool().unwrap());if accepted{assert!(donor.is_none());assert_eq!(serde_json::to_value(output.as_ref().unwrap()).unwrap(),serde_json::json!([row["push"]["value"]]));assert_eq!(step.progress().copied_bytes,std::mem::size_of::<u64>()+std::mem::size_of::<Option<u64>>()+std::mem::size_of::<usize>());}else{assert_eq!(donor,Some(row["push"]["value"].as_u64().unwrap()));assert!(output.as_ref().unwrap().is_empty());assert_eq!(step.progress(),Default::default());}debit(&mut bank,&mut fuel,step.progress(),turn.work);}
 let mut owner=crate::retirement::controlled::ControlledRetirement::new(output.take().unwrap()).map_err(|(e,_)|e).unwrap();for _ in 0..s["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty()&&retirement_actual.is_none(){break}let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||{let turn=crate::source_fixture::close_step(&mut retirement_actual,RetainedCloneGrant{maximum_items:1,..bank},fuel,owner.next_demand(4096),owner.next_computational_work(4096),|g,a|{let result=owner.step(g,a);crate::RetainedWorkOutcome{result,work:owner.last_turn_work()}});retirement_work=turn.work;turn.result}.unwrap());let p=step.progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,&mut fuel,p,retirement_work);}assert!(owner.terminal_is_empty());
}

#[test]fn paged_empty_storage_pays_its_actual_optional_header_before_installation(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let mut bank=crate::source_fixture::Wallet::from_profile(&row["stock"]);let mut output=None;let mut frame=crate::native_decoding::NativeReceivingEffect::default();type P=semio_framework_value_persistent::list::PagedList<u64,64>;let demand=<P as NativeSequenceCollection<u64>>::storage_demand(row["count"].as_u64().unwrap()as usize).unwrap();assert_eq!(row["retainedHeader"],"optional-storage");assert_eq!(demand.copy_bytes,std::mem::size_of::<Option<P>>());assert!(demand.copy_bytes>0);let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.loan(1,4096).maximum_capacity_bytes,&mut callback);
 for copy in [0,demand.copy_bytes]{let mut g=bank.loan(1,4096);g.maximum_copy_bytes=copy;let maximum=bank.work_remaining();let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||crate::source_fixture::receive(&mut control,g,bank.work_loan(maximum),|c|<P as NativeSequenceCollection<u64>>::admit_storage(&mut output,row["count"].as_u64().unwrap()as usize,&mut frame,c,maximum,g)));assert_eq!(heap,(0,0));let p=turn.result.unwrap().progress();assert_eq!(turn.work,if copy==0{0}else{1});assert_eq!(p.copied_bytes,copy);assert_eq!(output.is_some(),copy!=0);bank.post(p,turn.work,g,heap);}
 assert_eq!(serde_json::to_value(output.as_ref().unwrap().iter().copied().collect::<Vec<_>>()).unwrap(),row["empty"]);crate::source_fixture::close_owned(output.take().unwrap(),&mut bank,4096,100000);
}
